from pathlib import Path
import subprocess,json,hashlib,datetime,os
out=Path(__file__).resolve().parents[1];p=out/'external-api.rs';p.write_text('''use std::mem::{align_of,size_of};
use typst_core::entities::{style::{Style,Styles},style_chain::{StyleDelta,StyleChain},layout_types::{Length,Pt,TextStyle}};
fn main(){let l=Length::pt(3.0)+Length::em(2.0);let s=Style::Size(l);let d=StyleDelta{size:Some(l),..StyleDelta::empty()};let c=StyleChain::default_chain().push(d);assert_eq!(c.size(),25.0);let _:Pt=TextStyle::from(&c).size;assert_eq!(Styles::from_iter([s]).delta().size,Some(l));println!("{{\\\"length\\\":{},\\\"option_length\\\":{},\\\"option_f64\\\":{},\\\"style\\\":{},\\\"styles\\\":{},\\\"style_delta\\\":{},\\\"alignment\\\":{}}}",size_of::<Length>(),size_of::<Option<Length>>(),size_of::<Option<f64>>(),size_of::<Style>(),size_of::<Styles>(),size_of::<StyleDelta>(),align_of::<StyleDelta>());}
''');binary=out/'external-api';cmd=['rustc','--edition=2021',str(p),'--crate-name','ts1_external_api','--extern','typst_core=target/debug/libtypst_core.rlib','-L','dependency=target/debug/deps','-o',str(binary)];r=subprocess.run(cmd,capture_output=True,text=True);assert r.returncode==0,r.stderr;z=subprocess.run([str(binary)],capture_output=True,text=True);assert z.returncode==0,z.stderr;record=dict(utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),command=cmd,exit=r.returncode,source_sha256=hashlib.sha256(p.read_bytes()).hexdigest(),rlib_sha256=hashlib.sha256(Path('target/debug/libtypst_core.rlib').read_bytes()).hexdigest(),sizes=json.loads(z.stdout),runtime_exit=z.returncode);(out/'api-probe.json').write_text(json.dumps(record,indent=2)+'\n');binary.unlink();print(record)
